entryCriteria.formula:
AND(OR(CreatedBy.Profile.Name = 'Qantas CC Consultant',AND(OR(CONTAINS(CreatedBy.Profile.Name,'QCC Contact Center Agent'),CONTAINS(CreatedBy.Profile.Name,'QCC Customer Advocacy Agent')),NOT(ISPICKVAL(CreatedBy.Operational_Group__c, 'Team Leader')))) 
,OR(AND(Text(Type__c)='Payment (Credit Card)',Value__c>30000,Value__c<=150000) 
,AND(OR(Text(Type__c)='Payment (EFT)', Text(Type__c)='Ticket Refund EFT'),Value__c>30000,Value__c<=150000)
,AND(Text(Type__c)= 'Qantas Points',Amount__c>3000000,Amount__c<=15000000)
) 
)

AND(
OR(
/* Consultant Sydney/Other */
AND(OR(LastModifiedBy.Profile.Name = 'Qantas CC Consultant',AND(OR(CONTAINS(LastModifiedBy.Profile.Name,'QCC Contact Center Agent'),CONTAINS(LastModifiedBy.Profile.Name,'QCC Customer Advocacy Agent')),NOT(ISPICKVAL(LastModifiedBy.Operational_Group__c, 'Team Leader')))),
/* Consultant Other */
AND(OR(
Text(LastModifiedBy.Location__c) = 'Manila', Text(LastModifiedBy.Location__c) = 'Hobart',
Text(LastModifiedBy.Location__c) = 'Auckland',
Text(LastModifiedBy.Location__c) = 'Suva',
Text(LastModifiedBy.Location__c) = 'Capetown')
, OR(AND(Text(Type__c) =
'Qantas Points', Amount__c > Suggested_Maximum__c)
, AND(Text(Type__c) = 'Qantas Points', Amount__c > 0, ISBLANK(Suggested_Maximum__c))
, AND(Amount__c > 2,
OR(
Text(Type__c) = 'Lounge Passes'
)
)
, AND(Text(Type__c) = 'Payment (Credit Card)', Value__c > 500)
, AND(OR(Text(Type__c) = 'Payment (EFT)',Text(Type__c) = 'Ticket Refund EFT'), Value__c > 500)
, AND(Text(Type__c) = 'Travel vouchers', Value__c > 200)
))
/* Consultant Sydney */
, AND(Text(LastModifiedBy.Location__c) = 'Sydney',
OR(AND(Text(Type__c) = 'Payment (Credit Card)', Value__c > 5000)
, AND(OR(Text(Type__c) = 'Payment (EFT)',Text(Type__c) = 'Ticket Refund EFT'), Value__c > 5000)
, AND(Text(Type__c) = 'Travel vouchers', Value__c > 500),
AND(Amount__c > 4,
OR(
Text(Type__c) = 'Lounge Passes'
)
)
, AND(Text(Type__c) = 'Qantas Points', Amount__c > 20000)
))
)
/* Consultant Sydney/Other */
, AND(OR(CreatedBy.Profile.Name = 'Qantas CC Team Lead',AND( OR(CONTAINS(LastModifiedBy.Profile.Name,'QCC Contact Center Agent'),CONTAINS(LastModifiedBy.Profile.Name,'QCC Customer Advocacy Agent')),ISPICKVAL(CreatedBy.Operational_Group__c, 'Team Leader')) )
, OR(AND(Text(Type__c) = 'Payment (Credit Card)', Value__c > 2000)
, AND(OR(Text(Type__c) = 'Payment (EFT)',Text(Type__c) = 'Ticket Refund EFT'), Value__c > 2000)
, AND(Text(Type__c) = 'Travel vouchers', Value__c > 2500)
, AND(Text(Type__c) = 'Qantas Points', Amount__c > 25000)
)),
/* Operational Manager Other */
AND(OR(CreatedBy.Profile.Name = 'Qantas CC Operational Manager',CreatedBy.Profile.Name = 'QCC Operational Manager'), (Text(LastModifiedBy.Location__c) != 'Sydney')
, OR( AND(Text(Type__c) = 'Payment (Credit Card)', Value__c > 5000)
, AND(OR(Text(Type__c) = 'Payment (EFT)',Text(Type__c) = 'Ticket Refund EFT'), Value__c > 5000)
, AND(Text(Type__c) = 'Qantas Points', Amount__c > 100000)
)),
/* Operational Manager Sydney */
AND(OR(CreatedBy.Profile.Name = 'Qantas CC Operational Manager',CreatedBy.Profile.Name = 'QCC Operational Manager') ,(Text(LastModifiedBy.Location__c) = 'Sydney')
, OR(AND(Text(Type__c) = 'Payment (Credit Card)', Value__c > 10000)
, AND(OR(Text(Type__c) = 'Payment (EFT)',Text(Type__c) = 'Ticket Refund EFT'), Value__c > 10000)
, AND(Text(Type__c) = 'Qantas Points', Amount__c > 100000)
))
)
)
